// What the shaders share with the C++ core and the scripts: the people: their clip and body tables, face acts, helmets and the cooked asset's layout (render/agents people_*; the people shaders). Generated by tools/build/shader_contracts.py from tools/build/shader_contracts.json: edit the table, never this file.
// The shaders read the same through project/render/shaders/contracts/people.gdshaderinc; the scripts through
// CityCore::constants "shader" (SHADER_CONTRACTS_PEOPLE below, gathered in core/shader_contracts/all.h).
#pragma once

#include "core/shader_contracts/contract.h"

#include <cstdint>

namespace city {

// the clips a person's tables hold (people_boot.cpp CLIP_TABLE; people_pose.gdshaderinc clip_row, clip_frames, clip_seconds by sex; people_face.gdshaderinc act_face)
constexpr int PEOPLE_CLIPS = 24;
// the body variations (people_boot.cpp BODY_TABLE; people_pose.gdshaderinc walk_frames, body_female; people_face body_mood; three rows each in palm_rows and helmet_rows)
constexpr int PEOPLE_BODIES = 32;
// rows a variation takes in palm_rows and helmet_rows (people_boot.cpp PALM_ROWS)
constexpr int PEOPLE_HAND_ROWS = 3;
// an instance colour's alpha from here on is a clip, held (people_renderer.cpp, people_pose.gdshaderinc)
constexpr float PEOPLE_CLIP_CODE_BASE = float(2.0);
// the whole of an act, short of the next clip's number (people_renderer.cpp, people_pose.gdshaderinc)
constexpr float PEOPLE_ACT_SPAN = float(0.96);
// what a face does at a clip (people_boot.cpp FACE_ACTS, people_face.gdshaderinc)
constexpr int FACE_ACT_TALK = 1;
// as FACE_ACT_TALK
constexpr int FACE_ACT_LISTEN = 2;
// as FACE_ACT_TALK
constexpr int FACE_ACT_PHONE = 3;
// as FACE_ACT_TALK
constexpr int FACE_ACT_CROUCH = 4;
// the helmets' colours (helmets.cpp, people_helmet.gdshader)
constexpr int HELMET_COLOURS = 8;
// the things people wear (worn_things.cpp, people_worn.gdshader worn_bone, worn_at by body, worn_colours)
constexpr int WORN_THINGS = 4;
// the colours of one worn thing (worn_things.cpp, people_worn.gdshader worn_colours)
constexpr int WORN_COLOURS = 8;
// the cooked people (people_asset.cpp reads and checks them): a face row's channels and the rows side by side in face_table (people_face.gdshaderinc), a bone's texels in the palette and a value's (high bytes, then low; people_pose.gdshaderinc), the skeleton's bones (people_skin.gdshaderinc)
constexpr int PEOPLE_FACE_CHANNELS = 13;
constexpr int PEOPLE_FACE_SPAN = 8;
constexpr int PEOPLE_BONE_TEXELS = 3;
constexpr int PEOPLE_PALETTE_TEXELS = 2;
constexpr int PEOPLE_BONES = 53;
// a face vertex's UV2.x is its region plus this many a row of face_table; a palette value is fixed point over [-span, span] (people_asset.cpp; people_face.gdshaderinc, people_pose.gdshaderinc)
constexpr float PEOPLE_FACE_ROW_STEP = float(4.0);
constexpr float PEOPLE_PALETTE_SPAN = float(3.0);

// Every value above by the name the shaders give it, for the scripts.
constexpr ShaderContract SHADER_CONTRACTS_PEOPLE[] = {
	{ "PEOPLE_CLIPS", 1, { double(PEOPLE_CLIPS) } },
	{ "PEOPLE_BODIES", 1, { double(PEOPLE_BODIES) } },
	{ "PEOPLE_HAND_ROWS", 1, { double(PEOPLE_HAND_ROWS) } },
	{ "PEOPLE_CLIP_CODE_BASE", 1, { double(2.0) } },
	{ "PEOPLE_ACT_SPAN", 1, { double(0.96) } },
	{ "FACE_ACT_TALK", 1, { double(FACE_ACT_TALK) } },
	{ "FACE_ACT_LISTEN", 1, { double(FACE_ACT_LISTEN) } },
	{ "FACE_ACT_PHONE", 1, { double(FACE_ACT_PHONE) } },
	{ "FACE_ACT_CROUCH", 1, { double(FACE_ACT_CROUCH) } },
	{ "HELMET_COLOURS", 1, { double(HELMET_COLOURS) } },
	{ "WORN_THINGS", 1, { double(WORN_THINGS) } },
	{ "WORN_COLOURS", 1, { double(WORN_COLOURS) } },
	{ "PEOPLE_FACE_CHANNELS", 1, { double(PEOPLE_FACE_CHANNELS) } },
	{ "PEOPLE_FACE_SPAN", 1, { double(PEOPLE_FACE_SPAN) } },
	{ "PEOPLE_BONE_TEXELS", 1, { double(PEOPLE_BONE_TEXELS) } },
	{ "PEOPLE_PALETTE_TEXELS", 1, { double(PEOPLE_PALETTE_TEXELS) } },
	{ "PEOPLE_BONES", 1, { double(PEOPLE_BONES) } },
	{ "PEOPLE_FACE_ROW_STEP", 1, { double(4.0) } },
	{ "PEOPLE_PALETTE_SPAN", 1, { double(3.0) } },
};

} // namespace city
